@jit(nopython = True)
def jit_loop(array, fixed_val):
    out = np.zeros(len(array))
        for i in range(fixed_val, len(array)):
            if(i%100 == 0):
                print(i)
                
            data = array[i-fixed_val+1:i+1]
            mean_val = np.mean(data)
            diff = 0
            for j in range(len(data)):
                diff = diff + np.abs(data[j]-mean_val)
            out[i] = diff/mean_val
        return out
